#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    long long x = *(const long long*)a;
    long long y = *(const long long*)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main() {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;
    long long *a = (long long*)malloc(N * sizeof(long long));
    long long *b = (long long*)malloc(N * sizeof(long long));
    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &b[i]);

    long long total_base = 0;
    long long *m = (long long*)malloc(N * sizeof(long long));
    for (int i = 0; i < N; i++) {
        if (a[i] >= b[i]) {
            total_base += a[i] - b[i];
        }
        m[i] = (a[i] < b[i]) ? a[i] : b[i];
    }

    qsort(m, N, sizeof(long long), cmp);

    long long ans = total_base;
    int lim = K + 1;
    if (lim > N) lim = N;
    for (int i = 0; i < lim; i++) {
        ans += m[i];
    }

    printf("%lld\n", ans);

    free(a); free(b); free(m);
    return 0;
}
